import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as r}from"./app-1q43mSwl.js";var i=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/ASP.NET_Core/SQL%20Server%E8%BF%9B%E9%98%B6/01.%E7%AA%97%E5%8F%A3%E5%87%BD%E6%95%B0%E7%B2%BE%E9%80%9A.html","title":"窗口函数精通","lang":"zh-CN","frontmatter":{"title":"窗口函数精通","date":"2025-04-13T00:00:00.000Z","category":["SQL Server进阶"],"tag":["SQL Server","窗口函数","Window Function","数据分析"],"author":"Moklgy","order":1},"git":{"createdTime":1776079919000,"updatedTime":1776079919000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":10.48,"words":3144},"filePathRelative":"后端开发/ASP.NET_Core/SQL Server进阶/01.窗口函数精通.md"}`),a={name:`01.窗口函数精通.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="第一章-窗口函数精通" tabindex="-1"><a class="header-anchor" href="#第一章-窗口函数精通"><span>第一章：窗口函数精通</span></a></h1><blockquote><p><strong>窗口函数是 SQL 从&quot;会用&quot;到&quot;精通&quot;的分水岭。</strong> 掌握它，你的 SQL 表达能力直接跃升一个维度。</p></blockquote><hr><h2 id="一、窗口函数-vs-group-by-——-本质区别" tabindex="-1"><a class="header-anchor" href="#一、窗口函数-vs-group-by-——-本质区别"><span>一、窗口函数 vs GROUP BY —— 本质区别</span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>GROUP BY 的问题：</span></span>
<span class="line"><span>  SELECT DepartmentId, AVG(Salary) </span></span>
<span class="line"><span>  FROM Employees </span></span>
<span class="line"><span>  GROUP BY DepartmentId</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  → 每个部门只有一行结果</span></span>
<span class="line"><span>  → 原始行被&quot;压缩&quot;了</span></span>
<span class="line"><span>  → 你看不到每个员工的信息了</span></span>
<span class="line"><span></span></span>
<span class="line"><span>窗口函数的优势：</span></span>
<span class="line"><span>  SELECT </span></span>
<span class="line"><span>      EmployeeId, Name, DepartmentId, Salary,</span></span>
<span class="line"><span>      AVG(Salary) OVER(PARTITION BY DepartmentId) AS DeptAvgSalary</span></span>
<span class="line"><span>  FROM Employees</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  → 每行结果都保留</span></span>
<span class="line"><span>  → 每行多了一个&quot;部门平均工资&quot;列</span></span>
<span class="line"><span>  → 既能看个体，又能看整体</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌──────────┬──────┬──────┬────────┬──────────────┐</span></span>
<span class="line"><span>│EmployeeId│ Name │ Dept │ Salary │ DeptAvgSalary│</span></span>
<span class="line"><span>├──────────┼──────┼──────┼────────┼──────────────┤</span></span>
<span class="line"><span>│ 1        │ 张三 │ IT   │ 15000  │ 13333        │</span></span>
<span class="line"><span>│ 2        │ 李四 │ IT   │ 12000  │ 13333        │</span></span>
<span class="line"><span>│ 3        │ 王五 │ IT   │ 13000  │ 13333        │</span></span>
<span class="line"><span>│ 4        │ 赵六 │ HR   │ 10000  │ 11000        │</span></span>
<span class="line"><span>│ 5        │ 钱七 │ HR   │ 12000  │ 11000        │</span></span>
<span class="line"><span>└──────────┴──────┴──────┴────────┴──────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每个人都在，同时能看到部门平均值 ✅</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="二、窗口函数语法框架" tabindex="-1"><a class="header-anchor" href="#二、窗口函数语法框架"><span>二、窗口函数语法框架</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">函数名(</span><span style="color:#E06C75;">[参数]</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#E06C75;">    [PARTITION BY 分区列]</span><span style="color:#7F848E;font-style:italic;">        -- 按什么分组（不压缩行）</span></span>
<span class="line"><span style="color:#E06C75;">    [ORDER BY 排序列 [ASC|DESC]</span><span style="color:#ABB2BF;">] </span><span style="color:#7F848E;font-style:italic;">-- 分区内排序</span></span>
<span class="line"><span style="color:#E06C75;">    [ROWS/RANGE 窗口范围]</span><span style="color:#7F848E;font-style:italic;">        -- 计算范围（帧）</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>语法拆解：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OVER()                    → 整张表作为一个窗口</span></span>
<span class="line"><span>OVER(PARTITION BY dept)   → 按部门分窗口</span></span>
<span class="line"><span>OVER(ORDER BY salary)     → 整表排序</span></span>
<span class="line"><span>OVER(PARTITION BY dept ORDER BY salary) → 部门内按薪资排序</span></span>
<span class="line"><span></span></span>
<span class="line"><span>窗口帧（frame）：</span></span>
<span class="line"><span>ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW   → 从分区起点到当前行</span></span>
<span class="line"><span>ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING            → 前一行到后一行</span></span>
<span class="line"><span>ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING → 整个分区</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="三、排名函数-——-面试必考-top-3" tabindex="-1"><a class="header-anchor" href="#三、排名函数-——-面试必考-top-3"><span>三、排名函数 —— 面试必考 TOP 3</span></a></h2><h3 id="_3-1-row-number-——-连续编号-无重复" tabindex="-1"><a class="header-anchor" href="#_3-1-row-number-——-连续编号-无重复"><span>3.1 ROW_NUMBER() —— 连续编号，无重复</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 每个部门按薪资排名</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">    Name</span><span style="color:#ABB2BF;">, DepartmentId, Salary,</span></span>
<span class="line"><span style="color:#56B6C2;">    ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> DepartmentId </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Rn</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>结果：</span></span>
<span class="line"><span>┌──────┬──────┬────────┬────┐</span></span>
<span class="line"><span>│ Name │ Dept │ Salary │ Rn │</span></span>
<span class="line"><span>├──────┼──────┼────────┼────┤</span></span>
<span class="line"><span>│ 张三 │ IT   │ 15000  │ 1  │ ← 即使相同薪资也不会重复</span></span>
<span class="line"><span>│ 王五 │ IT   │ 13000  │ 2  │</span></span>
<span class="line"><span>│ 李四 │ IT   │ 12000  │ 3  │</span></span>
<span class="line"><span>│ 钱七 │ HR   │ 12000  │ 1  │ ← 新分区重新编号</span></span>
<span class="line"><span>│ 赵六 │ HR   │ 10000  │ 2  │</span></span>
<span class="line"><span>└──────┴──────┴────────┴────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-rank-——-有并列-有跳号" tabindex="-1"><a class="header-anchor" href="#_3-2-rank-——-有并列-有跳号"><span>3.2 RANK() —— 有并列，有跳号</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">    Name</span><span style="color:#ABB2BF;">, Salary,</span></span>
<span class="line"><span style="color:#56B6C2;">    RANK</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Rnk</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>结果：</span></span>
<span class="line"><span>┌──────┬────────┬─────┐</span></span>
<span class="line"><span>│ Name │ Salary │ Rnk │</span></span>
<span class="line"><span>├──────┼────────┼─────┤</span></span>
<span class="line"><span>│ 张三 │ 15000  │ 1   │</span></span>
<span class="line"><span>│ 王五 │ 13000  │ 2   │</span></span>
<span class="line"><span>│ 李四 │ 12000  │ 3   │ ← 并列第3</span></span>
<span class="line"><span>│ 钱七 │ 12000  │ 3   │ ← 并列第3</span></span>
<span class="line"><span>│ 赵六 │ 10000  │ 5   │ ← 跳过了4！</span></span>
<span class="line"><span>└──────┴────────┴─────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-3-dense-rank-——-有并列-不跳号" tabindex="-1"><a class="header-anchor" href="#_3-3-dense-rank-——-有并列-不跳号"><span>3.3 DENSE_RANK() —— 有并列，不跳号</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">    Name</span><span style="color:#ABB2BF;">, Salary,</span></span>
<span class="line"><span style="color:#56B6C2;">    DENSE_RANK</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> DRnk</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>结果：</span></span>
<span class="line"><span>┌──────┬────────┬──────┐</span></span>
<span class="line"><span>│ Name │ Salary │ DRnk │</span></span>
<span class="line"><span>├──────┼────────┼──────┤</span></span>
<span class="line"><span>│ 张三 │ 15000  │ 1    │</span></span>
<span class="line"><span>│ 王五 │ 13000  │ 2    │</span></span>
<span class="line"><span>│ 李四 │ 12000  │ 3    │ ← 并列第3</span></span>
<span class="line"><span>│ 钱七 │ 12000  │ 3    │ ← 并列第3</span></span>
<span class="line"><span>│ 赵六 │ 10000  │ 4    │ ← 紧接第4，不跳号</span></span>
<span class="line"><span>└──────┴────────┴──────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="三者对比" tabindex="-1"><a class="header-anchor" href="#三者对比"><span>三者对比</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>                  相同值    跳号?    适用场景</span></span>
<span class="line"><span>ROW_NUMBER()     不并列     N/A     分页、去重、取第一条</span></span>
<span class="line"><span>RANK()           并列       是      竞赛排名（标准排名）</span></span>
<span class="line"><span>DENSE_RANK()     并列       否      薪资等级、成绩档次</span></span>
<span class="line"><span></span></span>
<span class="line"><span>面试经典题：每个部门薪资前3名？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SELECT * FROM (</span></span>
<span class="line"><span>    SELECT </span></span>
<span class="line"><span>        Name, DepartmentId, Salary,</span></span>
<span class="line"><span>        DENSE_RANK() OVER(PARTITION BY DepartmentId ORDER BY Salary DESC) AS Rnk</span></span>
<span class="line"><span>    FROM Employees</span></span>
<span class="line"><span>) t</span></span>
<span class="line"><span>WHERE Rnk &lt;= 3;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-4-ntile-n-——-平均分桶" tabindex="-1"><a class="header-anchor" href="#_3-4-ntile-n-——-平均分桶"><span>3.4 NTILE(N) —— 平均分桶</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 把员工按薪资分成4组（四分位数）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">    Name</span><span style="color:#ABB2BF;">, Salary,</span></span>
<span class="line"><span style="color:#56B6C2;">    NTILE</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Quartile</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>结果：</span></span>
<span class="line"><span>┌──────┬────────┬──────────┐</span></span>
<span class="line"><span>│ Name │ Salary │ Quartile │</span></span>
<span class="line"><span>├──────┼────────┼──────────┤</span></span>
<span class="line"><span>│ 赵六 │ 10000  │ 1        │ ← 最低25%</span></span>
<span class="line"><span>│ 李四 │ 12000  │ 2        │</span></span>
<span class="line"><span>│ 钱七 │ 12000  │ 2        │</span></span>
<span class="line"><span>│ 王五 │ 13000  │ 3        │</span></span>
<span class="line"><span>│ 张三 │ 15000  │ 4        │ ← 最高25%</span></span>
<span class="line"><span>└──────┴────────┴──────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>场景：把用户分成高中低活跃度、销售额分档等</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="四、聚合窗口函数-——-不压缩行的统计" tabindex="-1"><a class="header-anchor" href="#四、聚合窗口函数-——-不压缩行的统计"><span>四、聚合窗口函数 —— 不压缩行的统计</span></a></h2><h3 id="_4-1-sum-avg-count-max-min-over" tabindex="-1"><a class="header-anchor" href="#_4-1-sum-avg-count-max-min-over"><span>4.1 SUM/AVG/COUNT/MAX/MIN OVER()</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">    Name</span><span style="color:#ABB2BF;">, DepartmentId, Salary,</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 部门总薪资</span></span>
<span class="line"><span style="color:#56B6C2;">    SUM</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> DepartmentId) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> DeptTotal,</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 部门平均</span></span>
<span class="line"><span style="color:#56B6C2;">    AVG</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> DepartmentId) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> DeptAvg,</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 部门人数</span></span>
<span class="line"><span style="color:#56B6C2;">    COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> DepartmentId) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> DeptCount,</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 个人占部门比例</span></span>
<span class="line"><span style="color:#56B6C2;">    CAST</span><span style="color:#ABB2BF;">(Salary * </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> / </span><span style="color:#56B6C2;">SUM</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> DepartmentId) </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">)) </span></span>
<span class="line"><span style="color:#C678DD;">        AS</span><span style="color:#ABB2BF;"> SalaryPercent,</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 全公司总薪资</span></span>
<span class="line"><span style="color:#56B6C2;">    SUM</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> CompanyTotal</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>结果：</span></span>
<span class="line"><span>┌──────┬──────┬────────┬──────────┬─────────┬──────────┬──────────────┬──────────────┐</span></span>
<span class="line"><span>│ Name │ Dept │ Salary │ DeptTotal│ DeptAvg │ DeptCount│ SalaryPercent│ CompanyTotal │</span></span>
<span class="line"><span>├──────┼──────┼────────┼──────────┼─────────┼──────────┼──────────────┼──────────────┤</span></span>
<span class="line"><span>│ 张三 │ IT   │ 15000  │ 40000    │ 13333   │ 3        │ 37.50        │ 62000        │</span></span>
<span class="line"><span>│ 王五 │ IT   │ 13000  │ 40000    │ 13333   │ 3        │ 32.50        │ 62000        │</span></span>
<span class="line"><span>│ 李四 │ IT   │ 12000  │ 40000    │ 13333   │ 3        │ 30.00        │ 62000        │</span></span>
<span class="line"><span>│ 钱七 │ HR   │ 12000  │ 22000    │ 11000   │ 2        │ 54.55        │ 62000        │</span></span>
<span class="line"><span>│ 赵六 │ HR   │ 10000  │ 22000    │ 11000   │ 2        │ 45.45        │ 62000        │</span></span>
<span class="line"><span>└──────┴──────┴────────┴──────────┴─────────┴──────────┴──────────────┴──────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一条SQL搞定：个人薪资 + 部门统计 + 个人占比 + 公司总计 ✅</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-累计求和-running-total" tabindex="-1"><a class="header-anchor" href="#_4-2-累计求和-running-total"><span>4.2 累计求和（Running Total）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 按日期累计销售额</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderDate, Amount,</span></span>
<span class="line"><span style="color:#56B6C2;">    SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> RunningTotal</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>结果：</span></span>
<span class="line"><span>┌────────────┬────────┬──────────────┐</span></span>
<span class="line"><span>│ OrderDate  │ Amount │ RunningTotal │</span></span>
<span class="line"><span>├────────────┼────────┼──────────────┤</span></span>
<span class="line"><span>│ 2024-01-01 │ 100    │ 100          │</span></span>
<span class="line"><span>│ 2024-01-02 │ 200    │ 300          │</span></span>
<span class="line"><span>│ 2024-01-03 │ 150    │ 450          │</span></span>
<span class="line"><span>│ 2024-01-04 │ 300    │ 750          │</span></span>
<span class="line"><span>│ 2024-01-05 │ 250    │ 1000         │</span></span>
<span class="line"><span>└────────────┴────────┴──────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>注意：ORDER BY 会隐式设置窗口帧为 </span></span>
<span class="line"><span>ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-移动平均-moving-average" tabindex="-1"><a class="header-anchor" href="#_4-3-移动平均-moving-average"><span>4.3 移动平均（Moving Average）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 最近3天移动平均</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderDate, Amount,</span></span>
<span class="line"><span style="color:#56B6C2;">    AVG</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#C678DD;">        ORDER BY</span><span style="color:#ABB2BF;"> OrderDate </span></span>
<span class="line"><span style="color:#C678DD;">        ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#D19A66;"> 2</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> CURRENT </span><span style="color:#C678DD;">ROW</span></span>
<span class="line"><span style="color:#ABB2BF;">    ) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> MovingAvg3</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> DailySales;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>结果：</span></span>
<span class="line"><span>┌────────────┬────────┬────────────┐</span></span>
<span class="line"><span>│ OrderDate  │ Amount │ MovingAvg3 │</span></span>
<span class="line"><span>├────────────┼────────┼────────────┤</span></span>
<span class="line"><span>│ 2024-01-01 │ 100    │ 100        │ ← 只有自己</span></span>
<span class="line"><span>│ 2024-01-02 │ 200    │ 150        │ ← (100+200)/2</span></span>
<span class="line"><span>│ 2024-01-03 │ 150    │ 150        │ ← (100+200+150)/3</span></span>
<span class="line"><span>│ 2024-01-04 │ 300    │ 216        │ ← (200+150+300)/3</span></span>
<span class="line"><span>│ 2024-01-05 │ 250    │ 233        │ ← (150+300+250)/3</span></span>
<span class="line"><span>└────────────┴────────┴────────────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="五、偏移函数-——-lag-lead-first-value-last-value" tabindex="-1"><a class="header-anchor" href="#五、偏移函数-——-lag-lead-first-value-last-value"><span>五、偏移函数 —— LAG / LEAD / FIRST_VALUE / LAST_VALUE</span></a></h2><h3 id="_5-1-lag-lead-——-看前一行-后一行" tabindex="-1"><a class="header-anchor" href="#_5-1-lag-lead-——-看前一行-后一行"><span>5.1 LAG() / LEAD() —— 看前一行 / 后一行</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 环比分析：每日销售额与前一天对比</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderDate, Amount,</span></span>
<span class="line"><span style="color:#56B6C2;">    LAG</span><span style="color:#ABB2BF;">(Amount, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> PrevDayAmount,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Amount - </span><span style="color:#56B6C2;">LAG</span><span style="color:#ABB2BF;">(Amount, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> DayOverDay,</span></span>
<span class="line"><span style="color:#56B6C2;">    LEAD</span><span style="color:#ABB2BF;">(Amount, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> NextDayAmount</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> DailySales;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>结果：</span></span>
<span class="line"><span>┌────────────┬────────┬───────────────┬────────────┬───────────────┐</span></span>
<span class="line"><span>│ OrderDate  │ Amount │ PrevDayAmount │ DayOverDay │ NextDayAmount │</span></span>
<span class="line"><span>├────────────┼────────┼───────────────┼────────────┼───────────────┤</span></span>
<span class="line"><span>│ 2024-01-01 │ 100    │ 0             │ 100        │ 200           │</span></span>
<span class="line"><span>│ 2024-01-02 │ 200    │ 100           │ 100        │ 150           │</span></span>
<span class="line"><span>│ 2024-01-03 │ 150    │ 200           │ -50        │ 300           │</span></span>
<span class="line"><span>│ 2024-01-04 │ 300    │ 150           │ 150        │ 250           │</span></span>
<span class="line"><span>│ 2024-01-05 │ 250    │ 300           │ -50        │ NULL          │</span></span>
<span class="line"><span>└────────────┴────────┴───────────────┴────────────┴───────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>LAG(列, 偏移量, 默认值)  → 往前看</span></span>
<span class="line"><span>LEAD(列, 偏移量, 默认值) → 往后看</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-2-first-value-last-value" tabindex="-1"><a class="header-anchor" href="#_5-2-first-value-last-value"><span>5.2 FIRST_VALUE() / LAST_VALUE()</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 每个部门薪资最高和最低的人</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">    Name</span><span style="color:#ABB2BF;">, DepartmentId, Salary,</span></span>
<span class="line"><span style="color:#56B6C2;">    FIRST_VALUE</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#C678DD;">        PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> DepartmentId </span></span>
<span class="line"><span style="color:#C678DD;">        ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#ABB2BF;">    ) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> HighestPaidName,</span></span>
<span class="line"><span style="color:#56B6C2;">    LAST_VALUE</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#C678DD;">        PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> DepartmentId </span></span>
<span class="line"><span style="color:#C678DD;">        ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">        ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> FOLLOWING</span></span>
<span class="line"><span style="color:#ABB2BF;">    ) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> LowestPaidName</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>⚠️ LAST_VALUE 陷阱：</span></span>
<span class="line"><span>默认窗口帧是 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW</span></span>
<span class="line"><span>所以 LAST_VALUE 默认只能看到&quot;当前行&quot;，不是分区最后一行！</span></span>
<span class="line"><span>必须显式设置 ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="六、高频业务场景" tabindex="-1"><a class="header-anchor" href="#六、高频业务场景"><span>六、高频业务场景</span></a></h2><h3 id="场景1-分页-——-row-number-实现" tabindex="-1"><a class="header-anchor" href="#场景1-分页-——-row-number-实现"><span>场景1：分页 —— ROW_NUMBER 实现</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 高性能分页（偏移量分页）</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> PagedData </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">        *, </span></span>
<span class="line"><span style="color:#56B6C2;">        ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> CreatedAt </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> RowNum</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#C678DD;"> Status</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Completed&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> PagedData</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> RowNum </span><span style="color:#C678DD;">BETWEEN</span><span style="color:#D19A66;"> 21</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> 40</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 第2页，每页20条</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- SQL Server 2012+ 更简洁的写法</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> Status</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Completed&#39;</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> CreatedAt </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#ABB2BF;">OFFSET </span><span style="color:#D19A66;">20</span><span style="color:#C678DD;"> ROWS</span><span style="color:#C678DD;"> FETCH</span><span style="color:#C678DD;"> NEXT</span><span style="color:#D19A66;"> 20</span><span style="color:#C678DD;"> ROWS</span><span style="color:#ABB2BF;"> ONLY;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="场景2-每组取第一条-去重保留最新" tabindex="-1"><a class="header-anchor" href="#场景2-每组取第一条-去重保留最新"><span>场景2：每组取第一条（去重保留最新）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 每个用户最近一次订单</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> LatestOrders </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">        *,</span></span>
<span class="line"><span style="color:#56B6C2;">        ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> UserId </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Rn</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> LatestOrders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> Rn </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="场景3-连续登录天数" tabindex="-1"><a class="header-anchor" href="#场景3-连续登录天数"><span>场景3：连续登录天数</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 找出连续登录3天以上的用户</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> LoginDays </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT DISTINCT</span><span style="color:#ABB2BF;"> UserId, </span><span style="color:#56B6C2;">CAST</span><span style="color:#ABB2BF;">(LoginTime </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> DATE</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> LoginDate</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> UserLogins</span></span>
<span class="line"><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">Groups </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">        UserId, LoginDate,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        -- 关键技巧：日期减去行号，连续的日期会得到相同的值</span></span>
<span class="line"><span style="color:#56B6C2;">        DATEADD</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">DAY</span><span style="color:#ABB2BF;">, -</span><span style="color:#56B6C2;">ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> UserId </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> LoginDate), LoginDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Grp</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> LoginDays</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> UserId, </span><span style="color:#56B6C2;">MIN</span><span style="color:#ABB2BF;">(LoginDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> StartDate, </span><span style="color:#56B6C2;">MAX</span><span style="color:#ABB2BF;">(LoginDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> EndDate,</span></span>
<span class="line"><span style="color:#56B6C2;">       COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> ConsecutiveDays</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Groups</span></span>
<span class="line"><span style="color:#C678DD;">GROUP BY</span><span style="color:#ABB2BF;"> UserId, Grp</span></span>
<span class="line"><span style="color:#C678DD;">HAVING</span><span style="color:#56B6C2;"> COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 3</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> UserId, StartDate;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>原理解析：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>登录日期      ROW_NUMBER    日期 - 行号 = Grp</span></span>
<span class="line"><span>2024-01-01    1             2023-12-31</span></span>
<span class="line"><span>2024-01-02    2             2023-12-31  ← 相同！连续</span></span>
<span class="line"><span>2024-01-03    3             2023-12-31  ← 相同！连续</span></span>
<span class="line"><span>2024-01-05    4             2024-01-01  ← 不同！断开了</span></span>
<span class="line"><span>2024-01-06    5             2024-01-01  ← 相同！连续</span></span>
<span class="line"><span></span></span>
<span class="line"><span>按 Grp 分组后，COUNT &gt;= 3 就是连续3天以上 ✅</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="场景4-累计占比-帕累托分析-80-20法则" tabindex="-1"><a class="header-anchor" href="#场景4-累计占比-帕累托分析-80-20法则"><span>场景4：累计占比（帕累托分析 / 80-20法则）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 找出贡献了80%销售额的TOP客户</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> CustomerSales </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">        CustomerId,</span></span>
<span class="line"><span style="color:#56B6C2;">        SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> TotalAmount</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#C678DD;">    GROUP BY</span><span style="color:#ABB2BF;"> CustomerId</span></span>
<span class="line"><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">Ranked </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">        CustomerId, TotalAmount,</span></span>
<span class="line"><span style="color:#56B6C2;">        SUM</span><span style="color:#ABB2BF;">(TotalAmount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> TotalAmount </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> RunningTotal,</span></span>
<span class="line"><span style="color:#56B6C2;">        SUM</span><span style="color:#ABB2BF;">(TotalAmount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> GrandTotal</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> CustomerSales</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">    CustomerId, TotalAmount,</span></span>
<span class="line"><span style="color:#56B6C2;">    CAST</span><span style="color:#ABB2BF;">(RunningTotal * </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> / GrandTotal </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">)) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> CumulativePercent</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Ranked</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> RunningTotal </span><span style="color:#56B6C2;">&lt;=</span><span style="color:#ABB2BF;"> GrandTotal * </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">8</span><span style="color:#7F848E;font-style:italic;"> -- 前80%</span></span>
<span class="line"><span style="color:#C678DD;">   OR</span><span style="color:#ABB2BF;"> TotalAmount </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">SELECT</span><span style="color:#56B6C2;"> MIN</span><span style="color:#ABB2BF;">(TotalAmount) </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Ranked </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> RunningTotal </span><span style="color:#56B6C2;">&lt;=</span><span style="color:#ABB2BF;"> GrandTotal * </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">8</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="场景5-同比环比分析" tabindex="-1"><a class="header-anchor" href="#场景5-同比环比分析"><span>场景5：同比环比分析</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 月度销售同比环比</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> MonthlySales </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#56B6C2;">        YEAR</span><span style="color:#ABB2BF;">(OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Y,</span></span>
<span class="line"><span style="color:#56B6C2;">        MONTH</span><span style="color:#ABB2BF;">(OrderDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> M,</span></span>
<span class="line"><span style="color:#56B6C2;">        SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> MonthAmount</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#C678DD;">    GROUP BY</span><span style="color:#56B6C2;"> YEAR</span><span style="color:#ABB2BF;">(OrderDate), </span><span style="color:#56B6C2;">MONTH</span><span style="color:#ABB2BF;">(OrderDate)</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">    Y, M, MonthAmount,</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 环比（上个月）</span></span>
<span class="line"><span style="color:#56B6C2;">    LAG</span><span style="color:#ABB2BF;">(MonthAmount, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Y, M) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> PrevMonth,</span></span>
<span class="line"><span style="color:#C678DD;">    CASE</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">        WHEN</span><span style="color:#56B6C2;"> LAG</span><span style="color:#ABB2BF;">(MonthAmount, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Y, M) </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">        THEN</span><span style="color:#56B6C2;"> CAST</span><span style="color:#ABB2BF;">((MonthAmount - </span><span style="color:#56B6C2;">LAG</span><span style="color:#ABB2BF;">(MonthAmount, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Y, M)) * </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">             / </span><span style="color:#56B6C2;">LAG</span><span style="color:#ABB2BF;">(MonthAmount, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Y, M) </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">))</span></span>
<span class="line"><span style="color:#C678DD;">    END</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> MoM_Percent,</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 同比（去年同月）</span></span>
<span class="line"><span style="color:#56B6C2;">    LAG</span><span style="color:#ABB2BF;">(MonthAmount, </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Y, M) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> SameMonthLastYear,</span></span>
<span class="line"><span style="color:#C678DD;">    CASE</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">        WHEN</span><span style="color:#56B6C2;"> LAG</span><span style="color:#ABB2BF;">(MonthAmount, </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Y, M) </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">        THEN</span><span style="color:#56B6C2;"> CAST</span><span style="color:#ABB2BF;">((MonthAmount - </span><span style="color:#56B6C2;">LAG</span><span style="color:#ABB2BF;">(MonthAmount, </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Y, M)) * </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">             / </span><span style="color:#56B6C2;">LAG</span><span style="color:#ABB2BF;">(MonthAmount, </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Y, M) </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">))</span></span>
<span class="line"><span style="color:#C678DD;">    END</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> YoY_Percent</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> MonthlySales</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Y, M;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="七、窗口帧-frame-详解" tabindex="-1"><a class="header-anchor" href="#七、窗口帧-frame-详解"><span>七、窗口帧（Frame）详解</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 窗口帧语法</span></span>
<span class="line"><span style="color:#C678DD;">ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">起点</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> AND</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">终点</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 起点/终点可以是：</span></span>
<span class="line"><span style="color:#C678DD;">UNBOUNDED</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#7F848E;font-style:italic;">    -- 分区第一行</span></span>
<span class="line"><span style="color:#ABB2BF;">N </span><span style="color:#C678DD;">PRECEDING</span><span style="color:#7F848E;font-style:italic;">            -- 当前行前N行</span></span>
<span class="line"><span style="color:#ABB2BF;">CURRENT </span><span style="color:#C678DD;">ROW</span><span style="color:#7F848E;font-style:italic;">            -- 当前行</span></span>
<span class="line"><span style="color:#ABB2BF;">N </span><span style="color:#C678DD;">FOLLOWING</span><span style="color:#7F848E;font-style:italic;">            -- 当前行后N行</span></span>
<span class="line"><span style="color:#C678DD;">UNBOUNDED</span><span style="color:#C678DD;"> FOLLOWING</span><span style="color:#7F848E;font-style:italic;">    -- 分区最后一行</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>常见帧定义：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW</span></span>
<span class="line"><span>  → 从分区起点到当前行（默认，累计计算）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING</span></span>
<span class="line"><span>  → 整个分区（等价于不加ORDER BY的PARTITION BY）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ROWS BETWEEN 2 PRECEDING AND CURRENT ROW</span></span>
<span class="line"><span>  → 前2行到当前行（3行移动窗口）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING</span></span>
<span class="line"><span>  → 前1行到后1行（3行居中窗口）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING</span></span>
<span class="line"><span>  → 当前行到分区末尾（反向累计）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="rows-vs-range-的区别" tabindex="-1"><a class="header-anchor" href="#rows-vs-range-的区别"><span>ROWS vs RANGE 的区别</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 有重复值时，ROWS 和 RANGE 行为不同</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ROWS：物理行，精确控制</span></span>
<span class="line"><span style="color:#56B6C2;">SUM</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">ROWS</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> CURRENT </span><span style="color:#C678DD;">ROW</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 严格按行计算，即使两行 Salary 相同也分别计算</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- RANGE：逻辑范围，相同值一起算</span></span>
<span class="line"><span style="color:#56B6C2;">SUM</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">RANGE</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#C678DD;"> UNBOUNDED</span><span style="color:#C678DD;"> PRECEDING</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> CURRENT </span><span style="color:#C678DD;">ROW</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 相同 Salary 的行会一起包含进来</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 💡 建议：除非你明确需要 RANGE 的语义，否则总是用 ROWS</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="八、递归-cte-——-树形结构和序列生成" tabindex="-1"><a class="header-anchor" href="#八、递归-cte-——-树形结构和序列生成"><span>八、递归 CTE —— 树形结构和序列生成</span></a></h2><h3 id="_8-1-基本语法" tabindex="-1"><a class="header-anchor" href="#_8-1-基本语法"><span>8.1 基本语法</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> RecursiveCTE </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 锚定成员（起始条件）</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> Id, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, ParentId, </span><span style="color:#D19A66;">0</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> Level</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Departments</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> ParentId </span><span style="color:#C678DD;">IS</span><span style="color:#C678DD;"> NULL</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#C678DD;">    UNION ALL</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 递归成员（循环条件）</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#D19A66;"> d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">r</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Level</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">1</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Departments d</span></span>
<span class="line"><span style="color:#C678DD;">    INNER JOIN</span><span style="color:#ABB2BF;"> RecursiveCTE r </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> r</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> RecursiveCTE</span></span>
<span class="line"><span style="color:#C678DD;">OPTION</span><span style="color:#ABB2BF;"> (MAXRECURSION </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">);  </span><span style="color:#7F848E;font-style:italic;">-- 防止无限递归</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-2-生成日期序列" tabindex="-1"><a class="header-anchor" href="#_8-2-生成日期序列"><span>8.2 生成日期序列</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 生成2024年所有日期</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> DateSeries </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#56B6C2;"> CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;2024-01-01&#39;</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> DATE</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Dt</span></span>
<span class="line"><span style="color:#C678DD;">    UNION ALL</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#56B6C2;"> DATEADD</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">DAY</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, Dt)</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> DateSeries</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> Dt </span><span style="color:#56B6C2;">&lt;</span><span style="color:#98C379;"> &#39;2024-12-31&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> Dt </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> DateSeries</span></span>
<span class="line"><span style="color:#C678DD;">OPTION</span><span style="color:#ABB2BF;"> (MAXRECURSION </span><span style="color:#D19A66;">366</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-3-组织架构展开" tabindex="-1"><a class="header-anchor" href="#_8-3-组织架构展开"><span>8.3 组织架构展开</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> OrgTree </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> Id, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, ManagerId, </span></span>
<span class="line"><span style="color:#56B6C2;">           CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">Name</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(MAX)) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> OrgPath,</span></span>
<span class="line"><span style="color:#D19A66;">           0</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> Level</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> ManagerId </span><span style="color:#C678DD;">IS</span><span style="color:#C678DD;"> NULL</span><span style="color:#7F848E;font-style:italic;">  -- CEO</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#C678DD;">    UNION ALL</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ManagerId</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#56B6C2;">           CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrgPath</span><span style="color:#ABB2BF;"> + </span><span style="color:#98C379;">&#39; &gt; &#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(MAX)),</span></span>
<span class="line"><span style="color:#D19A66;">           t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Level</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">1</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees e</span></span>
<span class="line"><span style="color:#C678DD;">    INNER JOIN</span><span style="color:#ABB2BF;"> OrgTree t </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ManagerId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#56B6C2;">    REPLICATE</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;    &#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">Level</span><span style="color:#ABB2BF;">) + </span><span style="color:#C678DD;">Name</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> OrgChart,</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrgPath, </span><span style="color:#C678DD;">Level</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> OrgTree</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrgPath;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>结果：</span></span>
<span class="line"><span>CEO张总</span></span>
<span class="line"><span>    VP李总</span></span>
<span class="line"><span>        总监王五</span></span>
<span class="line"><span>            经理赵六</span></span>
<span class="line"><span>            经理钱七</span></span>
<span class="line"><span>    VP刘总</span></span>
<span class="line"><span>        总监孙八</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="九、面试高频题精选" tabindex="-1"><a class="header-anchor" href="#九、面试高频题精选"><span>九、面试高频题精选</span></a></h2><h3 id="题1-第二高薪资" tabindex="-1"><a class="header-anchor" href="#题1-第二高薪资"><span>题1：第二高薪资</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 方法1：DENSE_RANK</span></span>
<span class="line"><span style="color:#C678DD;">SELECT DISTINCT</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> Salary, </span><span style="color:#56B6C2;">DENSE_RANK</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Rnk</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#ABB2BF;">) t </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> Rnk </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 方法2：子查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#56B6C2;"> MAX</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">SELECT</span><span style="color:#56B6C2;"> MAX</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 方法3：OFFSET</span></span>
<span class="line"><span style="color:#C678DD;">SELECT DISTINCT</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#ABB2BF;">OFFSET </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> ROWS</span><span style="color:#C678DD;"> FETCH</span><span style="color:#C678DD;"> NEXT</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> ROWS</span><span style="color:#ABB2BF;"> ONLY;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="题2-部门薪资中位数" tabindex="-1"><a class="header-anchor" href="#题2-部门薪资中位数"><span>题2：部门薪资中位数</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> DepartmentId, </span><span style="color:#56B6C2;">AVG</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> MedianSalary</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">        DepartmentId, Salary,</span></span>
<span class="line"><span style="color:#56B6C2;">        ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> DepartmentId </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Rn,</span></span>
<span class="line"><span style="color:#56B6C2;">        COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> DepartmentId) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Cnt</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#ABB2BF;">) t</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> Rn </span><span style="color:#C678DD;">IN</span><span style="color:#ABB2BF;"> (Cnt/</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">, Cnt/</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, (Cnt+</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">)/</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">GROUP BY</span><span style="color:#ABB2BF;"> DepartmentId;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="题3-找出连续3天销售额递增的日期段" tabindex="-1"><a class="header-anchor" href="#题3-找出连续3天销售额递增的日期段"><span>题3：找出连续3天销售额递增的日期段</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> DailySales </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#ABB2BF;">        SaleDate, Amount,</span></span>
<span class="line"><span style="color:#56B6C2;">        LAG</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> SaleDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> PrevAmount,</span></span>
<span class="line"><span style="color:#C678DD;">        CASE</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">            WHEN</span><span style="color:#ABB2BF;"> Amount </span><span style="color:#56B6C2;">&gt;</span><span style="color:#56B6C2;"> LAG</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> SaleDate) </span><span style="color:#C678DD;">THEN</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">            ELSE</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> </span></span>
<span class="line"><span style="color:#C678DD;">        END</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> IsIncreasing</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Sales</span></span>
<span class="line"><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">Groups </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> *,</span></span>
<span class="line"><span style="color:#56B6C2;">        SUM</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">CASE</span><span style="color:#C678DD;"> WHEN</span><span style="color:#ABB2BF;"> IsIncreasing </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 0</span><span style="color:#C678DD;"> THEN</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> ELSE</span><span style="color:#D19A66;"> 0</span><span style="color:#C678DD;"> END</span><span style="color:#ABB2BF;">) </span></span>
<span class="line"><span style="color:#C678DD;">            OVER</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> SaleDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Grp</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> DailySales</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> Grp, </span><span style="color:#56B6C2;">MIN</span><span style="color:#ABB2BF;">(SaleDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> StartDate, </span><span style="color:#56B6C2;">MAX</span><span style="color:#ABB2BF;">(SaleDate) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> EndDate,</span></span>
<span class="line"><span style="color:#56B6C2;">       COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> Days</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Groups</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> IsIncreasing </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span></span>
<span class="line"><span style="color:#C678DD;">GROUP BY</span><span style="color:#ABB2BF;"> Grp</span></span>
<span class="line"><span style="color:#C678DD;">HAVING</span><span style="color:#56B6C2;"> COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 至少连续2天递增 = 3天的序列</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="十、性能注意事项" tabindex="-1"><a class="header-anchor" href="#十、性能注意事项"><span>十、性能注意事项</span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>窗口函数性能要点：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. PARTITION BY 列建议有索引</span></span>
<span class="line"><span>   → 否则需要排序操作（Sort），大表很慢</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. ORDER BY 列建议有索引</span></span>
<span class="line"><span>   → 窗口函数内部需要排序</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 最佳索引：覆盖索引</span></span>
<span class="line"><span>   CREATE INDEX IX_Dept_Salary ON Employees(DepartmentId, Salary)</span></span>
<span class="line"><span>   INCLUDE (Name)</span></span>
<span class="line"><span>   → PARTITION BY DepartmentId ORDER BY Salary 不需要额外排序</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 避免在WHERE中直接使用窗口函数</span></span>
<span class="line"><span>   ❌ WHERE ROW_NUMBER() OVER(...) = 1</span></span>
<span class="line"><span>   ✅ 用子查询/CTE包装后再过滤</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5. 多个窗口函数如果OVER()相同，引擎只排序一次</span></span>
<span class="line"><span>   → 尽量保持相同的 PARTITION BY + ORDER BY</span></span>
<span class="line"><span></span></span>
<span class="line"><span>6. ROWS 通常比 RANGE 性能好</span></span>
<span class="line"><span>   → ROWS 不需要处理&quot;相同值&quot;的逻辑</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="十一、窗口函数速查表" tabindex="-1"><a class="header-anchor" href="#十一、窗口函数速查表"><span>十一、窗口函数速查表</span></a></h2><table><thead><tr><th>函数</th><th>类型</th><th>说明</th><th style="text-align:center;">是否需要 ORDER BY</th></tr></thead><tbody><tr><td>ROW_NUMBER()</td><td>排名</td><td>连续编号</td><td style="text-align:center;">✅</td></tr><tr><td>RANK()</td><td>排名</td><td>并列跳号</td><td style="text-align:center;">✅</td></tr><tr><td>DENSE_RANK()</td><td>排名</td><td>并列不跳号</td><td style="text-align:center;">✅</td></tr><tr><td>NTILE(N)</td><td>排名</td><td>平均分N桶</td><td style="text-align:center;">✅</td></tr><tr><td>SUM() OVER</td><td>聚合</td><td>求和</td><td style="text-align:center;">可选</td></tr><tr><td>AVG() OVER</td><td>聚合</td><td>平均</td><td style="text-align:center;">可选</td></tr><tr><td>COUNT() OVER</td><td>聚合</td><td>计数</td><td style="text-align:center;">可选</td></tr><tr><td>MAX() OVER</td><td>聚合</td><td>最大值</td><td style="text-align:center;">可选</td></tr><tr><td>MIN() OVER</td><td>聚合</td><td>最小值</td><td style="text-align:center;">可选</td></tr><tr><td>LAG(col, n)</td><td>偏移</td><td>前第n行</td><td style="text-align:center;">✅</td></tr><tr><td>LEAD(col, n)</td><td>偏移</td><td>后第n行</td><td style="text-align:center;">✅</td></tr><tr><td>FIRST_VALUE()</td><td>偏移</td><td>窗口第一个值</td><td style="text-align:center;">✅</td></tr><tr><td>LAST_VALUE()</td><td>偏移</td><td>窗口最后一个值</td><td style="text-align:center;">✅</td></tr><tr><td>PERCENT_RANK()</td><td>分布</td><td>百分比排名</td><td style="text-align:center;">✅</td></tr><tr><td>CUME_DIST()</td><td>分布</td><td>累计分布</td><td style="text-align:center;">✅</td></tr><tr><td>PERCENTILE_CONT()</td><td>分布</td><td>连续百分位</td><td style="text-align:center;">✅</td></tr><tr><td>PERCENTILE_DISC()</td><td>分布</td><td>离散百分位</td><td style="text-align:center;">✅</td></tr></tbody></table><hr><h2 id="十二、检验你的理解" tabindex="-1"><a class="header-anchor" href="#十二、检验你的理解"><span>十二、检验你的理解</span></a></h2><ol><li><p><strong>ROW_NUMBER、RANK、DENSE_RANK 三者的区别是什么？各自适用什么场景？</strong></p></li><li><p><strong><code>SUM(Amount) OVER(ORDER BY Date)</code> 为什么会变成累计求和？默认的窗口帧是什么？</strong></p></li><li><p><strong>为什么 LAST_VALUE 在 ORDER BY 后经常得到&quot;当前行&quot;而不是&quot;最后一行&quot;？怎么修复？</strong></p></li><li><p><strong>如何用窗口函数实现&quot;每组取最新一条&quot;？为什么不能在 WHERE 里直接用 ROW_NUMBER()？</strong></p></li><li><p><strong>连续登录天数的&quot;日期减行号&quot;技巧为什么能工作？如果有重复日期怎么办？</strong></p></li></ol>`,89)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};